//! Golden tests against committed ClickHouse output (generated by `tests/clickhouse/verify.sh --generate`).
//!
//! - Every supported type: the encoder reproduces, byte for byte, the Native block that ClickHouse returned for
//!   `tests/fixtures/<case>.sql`, from the same values.
//! - The decoder reads ClickHouse's own frames: `compress=1` responses (LZ4 from 26.3 and 26.8, ZSTD from 26.10)
//!   and `clickhouse compressor --zstd` output.
//! - The blocks that `verify.sh` inserts into live servers are binary snapshots of the encoder's output, so CI keeps
//!   them identical to what the code produces.

// Test code throughout: lets the helpers below use `unwrap` and `panic!` under the workspace lints.
#![cfg(test)]

use crucible_chfmt::{
    ArrayColumn, Block, CHUNK_SIZE, Column, Compression, MAX_BLOCK_ROWS, NullableColumn,
    StringColumn, TupleColumn, UuidColumn, decompress,
};

fn hex<const N: usize>(digits: &str) -> [u8; N] {
    let digits: Vec<u8> = digits.bytes().filter(|b| *b != b'-').collect();
    assert_eq!(digits.len(), 2 * N, "{digits:?}");
    let mut out = [0u8; N];
    for (byte, pair) in out.iter_mut().zip(digits.chunks(2)) {
        *byte = u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap();
    }
    out
}

