#[test]
fn low_cardinality_string_is_sent_as_string() {
    let string: &[u8] = include_bytes!("fixtures/string.native");
    let array: &[u8] = include_bytes!("fixtures/array_string.native");
    assert_eq!(
        native("string", "LowCardinality(String)", &v::string()),
        string
    );
    assert_eq!(
        native(
            "array_string",
            "Array(LowCardinality(String))",
            &v::array_string()
        ),
        array
    );
}

#[test]
fn datetime_utc_header() {
    // The encoder keeps the TableDef spelling `DateTime('UTC')`; only the header type differs from the fixture.
    let fixture: &[u8] = include_bytes!("fixtures/datetime.native");
    let clickhouse_header = [&[1, 8, 8][..], b"datetime", &[8], b"DateTime"].concat();
    let data = fixture.strip_prefix(clickhouse_header.as_slice()).unwrap();
    let expected = [&[1, 8, 8][..], b"datetime", &[15], b"DateTime('UTC')", data].concat();
    assert_eq!(
        native("datetime", "DateTime('UTC')", &v::datetime()),
        expected
    );
}

/// (method byte, uncompressed size) of every frame.
fn frames(mut bytes: &[u8]) -> Vec<(u8, usize)> {
    let mut frames = Vec::new();
    while !bytes.is_empty() {
        let size = |at: usize| u32::from_le_bytes(bytes[at..at + 4].try_into().unwrap()) as usize;
        frames.push((bytes[16], size(21)));
        bytes = &bytes[16 + size(17)..];
    }
    frames
}

/// The Native block of `tests/fixtures/compressed/large.sql`: one String row of 3,000,000 `a` bytes.
fn large() -> Vec<u8> {
    let mut native = [
        &[1, 1, 5][..],
        b"large",
        &[6],
        b"String",
        &[0xc0, 0x8d, 0xb7, 0x01],
    ]
    .concat();
    native.resize(native.len() + 3_000_000, b'a');
    native
}

fn large_chunks(method: u8) -> Vec<(u8, usize)> {
    vec![
        (method, CHUNK_SIZE),
        (method, CHUNK_SIZE),
        (method, large().len() - 2 * CHUNK_SIZE),
    ]
}

/// `compress=1` responses: 26.3 and 26.8 frame them with LZ4, 26.10 with ZSTD.
#[test]
fn decodes_clickhouse_compressed_responses() {
    let uint64: &[u8] = include_bytes!("fixtures/uint64.native");
    assert_eq!(
        decompress(include_bytes!("fixtures/compressed/response-uint64.lz4")).unwrap(),
        uint64
    );
    assert_eq!(
        decompress(include_bytes!("fixtures/compressed/response-uint64.zstd")).unwrap(),
        uint64
    );
    let large_lz4 = include_bytes!("fixtures/compressed/response-large.lz4");
    assert_eq!(frames(large_lz4), large_chunks(0x82));
    assert_eq!(decompress(large_lz4).unwrap(), large());
    let large_zstd = include_bytes!("fixtures/compressed/response-large.zstd");
    assert_eq!(frames(large_zstd), large_chunks(0x90));
    assert_eq!(decompress(large_zstd).unwrap(), large());
}

/// Output of `clickhouse compressor --zstd`.
#[test]
fn decodes_clickhouse_compressor_zstd_frames() {
    let string: &[u8] = include_bytes!("fixtures/string.native");
    assert_eq!(
        decompress(include_bytes!("fixtures/compressed/compressor-string.zstd")).unwrap(),
        string
    );
    let large_zstd = include_bytes!("fixtures/compressed/compressor-large.zstd");
    assert_eq!(frames(large_zstd), large_chunks(0x90));
    assert_eq!(decompress(large_zstd).unwrap(), large());
}

#[test]
fn encoder_chunks_like_clickhouse() {
    let mut value = StringColumn::default();
    value.push("a".repeat(3_000_000));
    let mut block = Block::new(1).unwrap();
    block.push("large", "String", &value).unwrap();
    assert_eq!(block.native(), large());
    let lz4 = block.encode(Compression::Lz4).unwrap();
    let zstd = block.encode(Compression::Zstd).unwrap();
    assert_eq!(frames(lz4.compressed()), large_chunks(0x82));
    assert_eq!(frames(zstd.compressed()), large_chunks(0x90));
}

/// Values for each column of `tests/clickhouse/all_types.tsv`.
fn all_types_column(name: &str) -> Box<dyn Column> {
    match name {
        "ord" => Box::new((0..8u32).collect::<Vec<_>>()),
        "uint8" | "saf_max_uint8" => Box::new(v::uint8()),
        "uint16" => Box::new(v::uint16()),
        "uint32" => Box::new(v::uint32()),
        "uint64" | "saf_sum_uint64" => Box::new(v::uint64()),
        "int64" | "saf_sum_int64" => Box::new(v::int64()),
        "float32" => Box::new(v::float32()),
        "float64" => Box::new(v::float64()),
        "uuid" => Box::new(v::uuid()),
        "string" | "saf_max_string" | "lc_string" => Box::new(v::string()),
        "fixed_string_8" => Box::new(v::fixed_string_8()),
        "fixed_string_16" => Box::new(v::fixed_string_16()),
        "fixed_string_32" => Box::new(v::fixed_string_32()),
        "date" => Box::new(v::date()),
        "datetime" | "saf_max_datetime" => Box::new(v::datetime()),
        "datetime64" | "saf_min_datetime64" | "saf_max_datetime64" => Box::new(v::datetime64()),
        "enum8" => Box::new(v::enum8()),
        "nullable_datetime64" => Box::new(v::nullable_datetime64()),
        "nullable_uint32" => Box::new(v::nullable_uint32()),
        "nullable_int32" => Box::new(v::nullable_int32()),
        "nullable_uint16" => Box::new(v::nullable_uint16()),
        "array_string"
        | "saf_group_uniq_array_string_16"
        | "saf_group_uniq_array_string_8"
        | "array_lc_string" => Box::new(v::array_string()),
        "array_uint8" | "saf_group_uniq_array_uint8_4" => Box::new(v::array_uint8()),
        "array_uint32" => Box::new(v::array_uint32()),
        "array_uint64" => Box::new(v::array_uint64()),
        "array_int64" => Box::new(v::array_int64()),
        "tuple_u16_u64" | "saf_sum_map_u16" => Box::new(v::tuple_u16_u64()),
        "tuple_u8_u64" | "saf_sum_map_u8" => Box::new(v::tuple_u8_u64()),
        other => panic!("no values for column {other}"),
    }
}

/// One block holding every type, with the TableDef type strings of `tests/clickhouse/all_types.tsv`.
#[test]
fn all_types_block() {
    let columns: Vec<(&str, &str)> = include_str!("clickhouse/all_types.tsv")
        .lines()
        .map(|line| {
            let mut fields = line.split('\t');
            (fields.next().unwrap(), fields.next().unwrap())
        })
        .collect();
    let data: Vec<Box<dyn Column>> = columns
        .iter()
        .map(|(name, _)| all_types_column(name))
        .collect();
    let mut block = Block::new(8).unwrap();
    for ((name, ty), data) in columns.iter().zip(&data) {
        block.push(name, ty, data.as_ref()).unwrap();
    }
    let lz4 = block.encode(Compression::Lz4).unwrap();
    let zstd = block.encode(Compression::Zstd).unwrap();
    assert_eq!(decompress(lz4.compressed()).unwrap(), block.native());
    assert_eq!(decompress(zstd.compressed()).unwrap(), block.native());
    insta::assert_binary_snapshot!("all_types_lz4.lz4", lz4.compressed().to_vec());
    insta::assert_binary_snapshot!("all_types_zstd.zstd", zstd.compressed().to_vec());
}

/// A block of the maximum size: 262,144 rows, about 5 MiB uncompressed, so several frames.
#[test]
fn max_rows_block() {
    let n: Vec<u32> = (0..MAX_BLOCK_ROWS as u32).map(|i| i % 16).collect();
    let mut s = StringColumn::with_capacity(MAX_BLOCK_ROWS, MAX_BLOCK_ROWS * 16);
    (0..MAX_BLOCK_ROWS).for_each(|i| s.push("ab".repeat(i % 16)));
    let mut block = Block::new(MAX_BLOCK_ROWS).unwrap();
    block.push("n", "UInt32", &n).unwrap();
    block.push("s", "LowCardinality(String)", &s).unwrap();
    let lz4 = block.encode(Compression::Lz4).unwrap();
    let zstd = block.encode(Compression::Zstd).unwrap();
    assert!(lz4.uncompressed_size() > 4 * CHUNK_SIZE);
    assert_eq!(
        frames(lz4.compressed()).len(),
        lz4.uncompressed_size().div_ceil(CHUNK_SIZE)
    );
    insta::assert_binary_snapshot!("max_rows_lz4.lz4", lz4.compressed().to_vec());
    insta::assert_binary_snapshot!("max_rows_zstd.zstd", zstd.compressed().to_vec());
}

/// One row of the aggregating table that `verify.sh` merges (a slice of `span_metrics` and `mcp_tool_rollup`).
struct Rollup {
    project_id: &'static str,
    minute: u32,
    environment: &'static str,
    marker_batch_seq: u64,
    marker_at: u32,
    count: u64,
    total_cost_nusd: i64,
    dur_hist: (&'static [u16], &'static [u64]),
    semconv_hist: (&'static [u8], &'static [u64]),
    capture_sources: &'static [u8],
    last_seen: i64,
}

const NIL: &str = "00000000-0000-0000-0000-000000000000";
const PROJECT: &str = "0193a1b2-7c3d-7e4f-8a5b-6c7d8e9f0a1b";
const EPOCH: &str = "0193a1b2-7c3d-7e4f-8a5b-000000000001";
/// 2026-11-17 09:30:00 and the first instant of its month, 2026-11-01 00:00:00.
const MINUTE: u32 = 1794907800;
const MONTH: u32 = 1793491200;

fn marker(marker_batch_seq: u64, marker_at: u32) -> Rollup {
    Rollup {
        project_id: NIL,
        minute: MONTH,
        environment: "",
        marker_batch_seq,
        marker_at,
        count: 0,
        total_cost_nusd: 0,
        dur_hist: (&[], &[]),
        semconv_hist: (&[], &[]),
        capture_sources: &[],
        last_seen: 0,
    }
}

fn rollup_block(rows: &[Rollup], compression: Compression) -> Vec<u8> {
    let mut project_id = UuidColumn::default();
    let mut minute = Vec::new();
    let mut environment = StringColumn::default();
    let mut marker_epoch = UuidColumn::default();
    let mut marker_batch_seq = Vec::new();
    let mut marker_at = Vec::new();
    let mut count = Vec::new();
    let mut total_cost_nusd = Vec::new();
    let mut dur_hist = TupleColumn::new(
        ArrayColumn::new(Vec::<u16>::new()),
        ArrayColumn::new(Vec::<u64>::new()),
    );
    let mut semconv_hist = TupleColumn::new(
        ArrayColumn::new(Vec::<u8>::new()),
        ArrayColumn::new(Vec::<u64>::new()),
    );
    let mut capture_sources = ArrayColumn::new(Vec::<u8>::new());
    let mut last_seen = Vec::new();
    for row in rows {
        project_id.push(hex(row.project_id));
        minute.push(row.minute);
        environment.push(row.environment);
        marker_epoch.push(hex(if row.project_id == NIL { EPOCH } else { NIL }));
        marker_batch_seq.push(row.marker_batch_seq);
        marker_at.push(row.marker_at);
        count.push(row.count);
        total_cost_nusd.push(row.total_cost_nusd);
        dur_hist.first_mut().push(row.dur_hist.0);
        dur_hist.second_mut().push(row.dur_hist.1);
        semconv_hist.first_mut().push(row.semconv_hist.0);
        semconv_hist.second_mut().push(row.semconv_hist.1);
        capture_sources.push(row.capture_sources);
        last_seen.push(row.last_seen);
    }
    let mut block = Block::new(rows.len()).unwrap();
    let columns: [(&str, &str, &dyn Column); 12] = [
        ("project_id", "UUID", &project_id),
        ("minute", "DateTime('UTC')", &minute),
        ("environment", "LowCardinality(String)", &environment),
        ("marker_epoch", "UUID", &marker_epoch),
        ("marker_batch_seq", "UInt64", &marker_batch_seq),
        (
            "marker_at",
            "SimpleAggregateFunction(max, DateTime('UTC'))",
            &marker_at,
        ),
        ("count", "SimpleAggregateFunction(sum, UInt64)", &count),
        (
            "total_cost_nusd",
            "SimpleAggregateFunction(sum, Int64)",
            &total_cost_nusd,
        ),
        (
            "dur_hist",
            "SimpleAggregateFunction(sumMap, Tuple(Array(UInt16), Array(UInt64)))",
            &dur_hist,
        ),
        (
            "semconv_hist",
            "SimpleAggregateFunction(sumMap, Tuple(Array(UInt8), Array(UInt64)))",
            &semconv_hist,
        ),
        (
            "capture_sources",
            "SimpleAggregateFunction(groupUniqArrayArray(4), Array(UInt8))",
            &capture_sources,
        ),
        (
            "last_seen",
            "SimpleAggregateFunction(max, DateTime64(6, 'UTC'))",
            &last_seen,
        ),
    ];
    for (name, ty, data) in columns {
        block.push(name, ty, data).unwrap();
    }
    block.encode(compression).unwrap().compressed().to_vec()
}

/// Two blocks for one aggregating table: the `prod` row of each shares a key, so a merge adds them
/// (`tests/clickhouse/sum_map.tsv`); each block carries its own marker row.
#[test]
fn sum_map_blocks() {
    let first = [
        marker(100, MINUTE + 60),
        Rollup {
            project_id: PROJECT,
            minute: MINUTE,
            environment: "dev",
            marker_batch_seq: 0,
            marker_at: 0,
            count: 1,
            total_cost_nusd: -5,
            dur_hist: (&[7], &[1]),
            semconv_hist: (&[0], &[1]),
            capture_sources: &[2],
            last_seen: 1794907800500000,
        },
        Rollup {
            project_id: PROJECT,
            minute: MINUTE,
            environment: "prod",
            marker_batch_seq: 0,
            marker_at: 0,
            count: 2,
            total_cost_nusd: 100,
            dur_hist: (&[3, 40], &[1, 1]),
            semconv_hist: (&[1], &[2]),
            capture_sources: &[1],
            last_seen: 1794907801000000,
        },
    ];
    let second = [
        marker(200, MINUTE + 120),
        Rollup {
            project_id: PROJECT,
            minute: MINUTE,
            environment: "prod",
            marker_batch_seq: 0,
            marker_at: 0,
            count: 3,
            total_cost_nusd: 50,
            dur_hist: (&[3, 41], &[2, 5]),
            semconv_hist: (&[1, 5], &[1, 1]),
            capture_sources: &[1, 3],
            last_seen: 1794907802000000,
        },
    ];
    insta::assert_binary_snapshot!("sum_map_1.lz4", rollup_block(&first, Compression::Lz4));
    insta::assert_binary_snapshot!("sum_map_2.zstd", rollup_block(&second, Compression::Zstd));
}
